"""Compile the RPG scores with the SDK's A3 encoder into C++20 assets."""

import argparse
import ast
import json
import re
import runpy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SONGS = (
    "dewlight_grove", "lantern_square", "sunward_road",
    "clockwork_hollow", "moonlit_quay", "homeward_stars",
)


def generate(compiler):
    encoder = runpy.run_path(str(compiler))
    headers = [
        "/* Generated by tools/generate_music.py; do not edit. */",
        "#pragma once", '#include "music_catalog.h"', "#include <avm/audio.h>", "",
        "struct MusicTrack {",
        "    void const AVM_PROGMEM* data;",
        "    char const AVM_PROGMEM* title;",
        "};", "",
    ]
    entries = []
    for song in SONGS:
        source = ROOT / f"assets/music/{song}.avms"
        text = source.read_text(encoding="utf-8")
        title = ast.literal_eval(re.search(r'^title\s+(".*")$', text, re.MULTILINE)[1])
        data = encoder["compile_source"](text, source)
        header = encoder["c_array"](data, f"{song.upper()}_MUSIC")
        header = header.replace("/* Generated by avm_music.py. */\n#include <avm/audio.h>\n", "")
        headers.append(header.replace("static const uint64_t", "constexpr uint64_t").replace(
            "static const AVM_PROGMEM struct", "constexpr AVM_PROGMEM struct"))
        headers.append(f"constexpr char AVM_PROGMEM {song.upper()}_TITLE[] = {json.dumps(title)};\n")
        entries.append(f"    {{{song.upper()}_MUSIC, {song.upper()}_TITLE}},")
    headers += ["constexpr MusicTrack AVM_PROGMEM MUSIC_TRACKS[] = {", *entries, "};",
                "static_assert(sizeof(MUSIC_TRACKS) / sizeof(MUSIC_TRACKS[0]) == MUSIC_COUNT);", ""]
    return "\n".join(headers)


def generate_catalog():
    return "\n".join([
        "/* Generated by tools/generate_music.py; do not edit. */",
        "#pragma once", "#include <stdint.h>", "", "enum MUSIC_TRACK : uint8_t {",
        *[f"    MUSIC_{song.upper()}," for song in SONGS], "    MUSIC_COUNT", "};", "",
    ])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--compiler", type=Path, required=True)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    for name, header in (("music.h", generate(args.compiler)), ("music_catalog.h", generate_catalog())):
        output = ROOT / "generated" / name
        if args.check:
            if not output.exists() or output.read_text(encoding="utf-8") != header:
                raise SystemExit(
                    f"{output.name} is stale; run tools/generate_music.py --compiler <avm_music.py>"
                )
        else:
            output.write_text(header, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
